Rules.InvariantScript:
If(
    IsBlank(
        First(
            Filter(
                tbl_ReaOcorrencias,
                Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = ThisItem.identificacao
            )
        ).Veiculo_identificacao
    ),
    "Operacional",
    "Baixado"
)

// Garante que há um item selecionado
If(
    IsBlank(CurrentItem),
    Notify(
        "Nenhum item selecionado.",
        NotificationType.Warning
    ),
    With(
        {_item: CurrentItem},
        // 1) REGISTRA NO HISTÓRICO
        Set(
            _histResult,
            Patch(
                tbl_gestaoVeiculosReaHistorico,
                Defaults(tbl_gestaoVeiculosReaHistorico),
                {
                    ID_FK: _item.ID,
                    Aeroporto: _item.aeroporto.Value,
                    Identificacao: _item.identificacao,
                    Status: _item.status,
                    Ativo: _item.ativo
                }
            )
        );
        // Verifica se houve erro no Patch do histórico
        If(
            !IsEmpty(
                Errors(
                    tbl_gestaoVeiculosReaHistorico,
                    _histResult
                )
            ),
            Notify(
                "Falha ao registrar no histórico: " & First(
                    Errors(
                        tbl_gestaoVeiculosReaHistorico,
                        _histResult
                    )
                ).Message,
                NotificationType.Error
            ),
            // 2) EXCLUI O REGISTRO NA TABELA PRINCIPAL (garantido por ID)
// Usamos RemoveIf por ID para não depender da referência do registro em memória
            RemoveIf(
                tbl_gestaoVeiculosRea,
                ID = _item.ID
            );
            // 3) Valida a exclusão
            If(
                IsEmpty(Errors(tbl_gestaoVeiculosRea)),
                // SUCESSO: atualiza a tela/estado e avisa
                Concurrent(
                    Refresh(tbl_gestaoVeiculosRea),
                    UpdateContext(
                        {
                            CurrentItem: Blank(),
                            isItemSelected: false,
                            newMode: false,
                            deleteMode: false
                        }
                    )
                ),
                Notify(
                    "Registro movido para o histórico e excluído com sucesso.",
                    NotificationType.Success
                ),
                // FALHA NA EXCLUSÃO
                Notify(
                    "Falha ao excluir o registro: " & First(Errors(tbl_gestaoVeiculosRea)).Message,
                    NotificationType.Error
                )
            )
        )
    )
