Rules.InvariantScript:
ResetForm(Form1);
UpdateContext(
    {
        newMode: false,
        editMode: false,
        isItemSelected: false
    }
);

UpdateContext(
    {
        CurrentItem: Self.LastSubmit,
        isItemSelected: false
    }
);
Patch(
    tbl_gestaoVeiculosReaHistorico,
    Defaults(tbl_gestaoVeiculosReaHistorico),
    {
        ID_FK: Self.LastSubmit.ID,
        Aeroporto: Self.LastSubmit.aeroporto.Value,
        Modelo: Self.LastSubmit.modelo,
        Identificacao: Self.LastSubmit.identificacao,
        Status: Self.LastSubmit.status,
        Ativo: Self.LastSubmit.ativo
    }
);
Notify(
    "Success",
    NotificationType.Success
);
ResetForm(Form1);
UpdateContext(
    {
        newMode: false,
        editMode: false,
        CurrentItem: Blank(),
        isItemSelected: false
    }
);

If(
    ThisItem.Ativo,
    If(
        IsBlank(
            First(
                Filter(
                    tbl_ReaOcorrencias,
                    Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = ThisItem.Identificacao
                )
            ).Veiculo_identificacao
        ),
        "Operacional",
        "Baixado"
    ),
    "Desativado"
)

ResetForm(Form1);
UpdateContext(
    {
        newMode: false,
        editMode: false,
        CurrentItem: Blank(),
        isItemSelected: false
    }
);

SubmitForm(Form1)
